def create_hub(name, connections):
    return {'name': name, 'connections': list(connections)}

def create_project(hub, name):
    return {'name': name, 'hub': hub['name'], 'connections': list(hub['connections'])}

hub = create_hub('ml-hub-east', ['azure-openai', 'ai-search'])
projects = [create_project(hub, n) for n in ['support-bot', 'doc-summarizer']]

print(f"Hub: {hub['name']} | shared connections: {len(hub['connections'])}")
for p in projects:
    print(f"Project {p['name']} inherits: {', '.join(p['connections'])}")
